-- MembershipRole: grow from the placeholder {OWNER, MEMBER} to the six
-- PRD §2.3 tiers. Existing MEMBER rows map to MANAGER (closest analog to
-- "a regular contributor" in the old two-tier model) — this is a data
-- migration, not just a type swap, so it's hand-written rather than
-- generated by `prisma migrate dev`.
ALTER TYPE "MembershipRole" RENAME TO "MembershipRole_old";
CREATE TYPE "MembershipRole" AS ENUM ('OWNER', 'ADMIN', 'EXECUTIVE', 'MANAGER', 'REVIEWER', 'GUEST');

ALTER TABLE "memberships" ALTER COLUMN "role" DROP DEFAULT;
ALTER TABLE "memberships" ALTER COLUMN "role" TYPE "MembershipRole" USING (
  CASE "role"::text
    WHEN 'MEMBER' THEN 'MANAGER'
    ELSE "role"::text
  END
)::"MembershipRole";
ALTER TABLE "memberships" ALTER COLUMN "role" SET DEFAULT 'MANAGER';

DROP TYPE "MembershipRole_old";

-- MembershipStatus: add SUSPENDED (ADM-02) — additive, no existing rows affected.
ALTER TYPE "MembershipStatus" ADD VALUE 'SUSPENDED';

-- Invitation (ADM-02: invite members).
CREATE TYPE "InvitationStatus" AS ENUM ('PENDING', 'ACCEPTED', 'REVOKED');

CREATE TABLE "invitations" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "role" "MembershipRole" NOT NULL,
    "tokenHash" TEXT NOT NULL,
    "invitedById" TEXT NOT NULL,
    "status" "InvitationStatus" NOT NULL DEFAULT 'PENDING',
    "expiresAt" TIMESTAMP(3) NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "acceptedAt" TIMESTAMP(3),

    CONSTRAINT "invitations_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "invitations_tokenHash_key" ON "invitations"("tokenHash");
CREATE INDEX "invitations_tenantId_idx" ON "invitations"("tenantId");

ALTER TABLE "invitations" ADD CONSTRAINT "invitations_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "invitations" ADD CONSTRAINT "invitations_invitedById_fkey" FOREIGN KEY ("invitedById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
